// This file is generated by AI.

// 实时预览指示器的状态推进规则测试。
//
// 三条"看代码看不出来"的引擎约定, 改错只表现为图标显示得不太对, 很难从界面追溯到原因:
// 1. 引擎上报的 `sentenceId` 是**停止指针** (执行完第 L 行 0 起算后为 L), 因此"回灌值 == 目标行号"
//    才算执行完成;
// 2. 回灌是**异步且会迟到**的: 把"回灌值不等于目标行"判成失败会出现假失败, 这类回灌一律读作
//    "预览已经不在这一行上";
// 3. 快进会在上限处为长演出停下 (`preview.event.fast-preview-timeout`), 那才是失败。

import { describe, expect, it } from 'vitest';

import {
  applyFastPreviewTimeoutToLivePreviewMarker,
  applyStageSnapshotToLivePreviewMarker,
  isFastPreviewTimeoutForLivePreviewMarker,
  isLivePreviewTargetExecuted,
  isStageSnapshotForLivePreviewMarker,
  sameLivePreviewMarker,
  type LivePreviewMarker,
} from '../src/preview/live-preview';

/** 一条"停在第 5 行等结果"的指示器 (Monaco 行号, 1 起算) */
function executingMarker(overrides: Partial<LivePreviewMarker> = {}): LivePreviewMarker {
  return {
    docPath: 'C:\\project\\game\\scene\\start.txt',
    line: 5,
    phase: 'executing',
    sceneName: 'start.txt',
    ...overrides,
  };
}

describe('isLivePreviewTargetExecuted', () => {
  it('引擎回灌的停止指针等于目标行号 = 目标行执行完了', () => {
    // 目标行是 Monaco 行号 5 (语句指针 4), 快进循环执行完它之后指针停在 5, 回灌的就是 5
    expect(isLivePreviewTargetExecuted({ line: 5 }, 5)).toBe(true);
    expect(isLivePreviewTargetExecuted({ line: 1 }, 1)).toBe(true);
  });

  it('指针在目标行之前说明还没执行到', () => {
    expect(isLivePreviewTargetExecuted({ line: 5 }, 4)).toBe(false);
  });

  it('指针越过目标行说明引擎自己往下跑了', () => {
    expect(isLivePreviewTargetExecuted({ line: 5 }, 6)).toBe(false);
  });
});

describe('applyStageSnapshotToLivePreviewMarker', () => {
  it('引擎停到目标行 -> 已执行', () => {
    const next = applyStageSnapshotToLivePreviewMarker(executingMarker(), {
      sceneName: 'start.txt',
      sentenceId: 5,
    });
    expect(next.phase).toBe('done');
    expect(next.line).toBe(5);
  });

  it('引擎停在别处 -> 已越过, 而不是失败', () => {
    // 迟到的旧回灌报的是别的指针, 把它判成失败就会刚点过去就冒出一个红叉
    for (const sentenceId of [2, 4, 9, 60]) {
      const next = applyStageSnapshotToLivePreviewMarker(executingMarker(), { sceneName: 'start.txt', sentenceId });
      expect(next.phase).toBe('passed');
    }
  });

  it('缺 sentenceId 的快照不改变状态', () => {
    const marker = executingMarker();
    expect(applyStageSnapshotToLivePreviewMarker(marker, { sceneName: 'start.txt' })).toEqual(marker);
  });

  it('已越过之后引擎报出目标行, 改判为已执行 (那次才是权威答案)', () => {
    const next = applyStageSnapshotToLivePreviewMarker(executingMarker({ phase: 'passed' }), {
      sceneName: 'start.txt',
      sentenceId: 5,
    });
    expect(next.phase).toBe('done');
  });

  it('已越过之后又是一条别的行 -> 保持已越过', () => {
    const next = applyStageSnapshotToLivePreviewMarker(executingMarker({ phase: 'passed' }), {
      sceneName: 'start.txt',
      sentenceId: 60,
    });
    expect(next.phase).toBe('passed');
  });

  it('绿可以覆盖红: 超时的陈旧判定不该永远留着', () => {
    const failed = executingMarker({ phase: 'failed' });
    expect(applyStageSnapshotToLivePreviewMarker(failed, { sceneName: 'start.txt', sentenceId: 5 }).phase).toBe('done');
  });

  it('已经确证执行过的绿不会被引擎继续往下跑改写', () => {
    const done = executingMarker({ phase: 'done' });
    expect(applyStageSnapshotToLivePreviewMarker(done, { sceneName: 'start.txt', sentenceId: 5 })).toEqual(done);
    expect(applyStageSnapshotToLivePreviewMarker(done, { sceneName: 'start.txt', sentenceId: 9 })).toEqual(done);
  });
});

describe('isStageSnapshotForLivePreviewMarker', () => {
  it('本场景的快照才作数', () => {
    expect(isStageSnapshotForLivePreviewMarker(executingMarker(), { sceneName: 'start.txt', sentenceId: 5 })).toBe(
      true
    );
    expect(isStageSnapshotForLivePreviewMarker(executingMarker(), { sceneName: 'other.txt', sentenceId: 5 })).toBe(
      false
    );
  });

  it('同场景内指针是几都收 —— 越过目标行的回灌另有含义, 不能丢', () => {
    expect(isStageSnapshotForLivePreviewMarker(executingMarker(), { sceneName: 'start.txt', sentenceId: 60 })).toBe(
      true
    );
  });

  it('引擎没报场景名 / 本机拿不到场景名时不否决', () => {
    expect(isStageSnapshotForLivePreviewMarker(executingMarker(), { sentenceId: 5 })).toBe(true);
    expect(
      isStageSnapshotForLivePreviewMarker(executingMarker({ sceneName: '' }), {
        sceneName: 'start.txt',
        sentenceId: 5,
      })
    ).toBe(true);
  });
});

describe('applyFastPreviewTimeoutToLivePreviewMarker', () => {
  it('快进没走到目标行 -> 未能执行', () => {
    const next = applyFastPreviewTimeoutToLivePreviewMarker(executingMarker());
    expect(next.phase).toBe('failed');
  });

  it('已经落定的结果不再改变', () => {
    for (const phase of ['done', 'passed', 'failed'] as const) {
      const marker = executingMarker({ phase });
      expect(applyFastPreviewTimeoutToLivePreviewMarker(marker)).toEqual(marker);
    }
  });
});

describe('isFastPreviewTimeoutForLivePreviewMarker', () => {
  it('超时事件说的就是这次跳转才作数', () => {
    // 目标行是 Monaco 行号 5, 编辑器发的 `sentenceId` 恰好也是 5 (它就是停止指针)
    expect(
      isFastPreviewTimeoutForLivePreviewMarker(executingMarker(), {
        sceneName: 'start.txt',
        targetSentenceId: 5,
        sentenceId: 2,
      })
    ).toBe(true);
    // 编辑器已经移到别的行, 这个超时说的是上一次同步
    expect(
      isFastPreviewTimeoutForLivePreviewMarker(executingMarker(), {
        sceneName: 'start.txt',
        targetSentenceId: 11,
        sentenceId: 2,
      })
    ).toBe(false);
  });

  it('别的场景的超时事件不作数', () => {
    expect(
      isFastPreviewTimeoutForLivePreviewMarker(executingMarker(), {
        sceneName: 'other.txt',
        targetSentenceId: 5,
      })
    ).toBe(false);
  });

  it('没有 targetSentenceId 时按场景判定', () => {
    expect(isFastPreviewTimeoutForLivePreviewMarker(executingMarker(), { sceneName: 'start.txt' })).toBe(true);
  });
});

/*
 * `sameLivePreviewMarker`: "值没变就不写 store" 的判据。
 *
 * `preview/client.ts` 的 `syncScene` 每次都会新造一个 marker 对象 (原地打字、同一行反复同步也是
 * 如此), 若 store 无条件接受, 行号旁的指示器装饰就会被拆掉重画 —— 它跟着光标走, 看起来就是
 * "编辑器一直在闪"。
 */
describe('sameLivePreviewMarker', () => {
  const marker: LivePreviewMarker = { docPath: 'a.txt', line: 5, phase: 'executing', sceneName: 'start.txt' };

  it('内容相同 (新对象) 算没变', () => {
    expect(sameLivePreviewMarker({ ...marker }, { ...marker })).toBe(true);
  });

  it('任一项不同就算变了', () => {
    expect(sameLivePreviewMarker(marker, { ...marker, phase: 'done' })).toBe(false);
    expect(sameLivePreviewMarker(marker, { ...marker, line: 6 })).toBe(false);
    expect(sameLivePreviewMarker(marker, { ...marker, docPath: 'b.txt' })).toBe(false);
    expect(sameLivePreviewMarker(marker, { ...marker, sceneName: 'other.txt' })).toBe(false);
  });

  it('null 与 undefined 等价, 两者之间算没变', () => {
    expect(sameLivePreviewMarker(null, null)).toBe(true);
    expect(sameLivePreviewMarker(undefined, undefined)).toBe(true);
    expect(sameLivePreviewMarker(null, undefined)).toBe(true);
  });

  it('有值与 null 互相算变了（清空 / 点亮必须通知）', () => {
    expect(sameLivePreviewMarker(marker, null)).toBe(false);
    expect(sameLivePreviewMarker(null, marker)).toBe(false);
  });

  it('同一个实例算没变', () => {
    expect(sameLivePreviewMarker(marker, marker)).toBe(true);
  });
});
